export interface SplitBillResult {
  totalBill: number;      // Original bill amount
  tipPercent: number;     // Tip percentage used
  totalTip: number;       // Calculated tip amount
  totalWithTip: number;   // Bill + tip
  numPeople: number;      // Number of people splitting
  perPerson: number;      // Amount each person pays
  tipPerPerson: number;   // Tip amount per person
}

function roundToTwoDecimals(value: number): number {
  return Math.round(value * 100) / 100;
}

export function splitBill(
  billAmount: number,
  tipPercent: number,
  numPeople: number
): SplitBillResult {
  // Input validation (R3)
  if (billAmount < 0) {
    throw new Error('Bill amount cannot be negative');
  }

  if (tipPercent < 0) {
    throw new Error('Tip percentage cannot be negative');
  }

  if (numPeople < 1) {
    throw new Error('Number of people must be at least 1');
  }

  if (!Number.isInteger(numPeople)) {
    throw new Error('Number of people must be an integer');
  }

  // Calculate tip and totals (R1, R2)
  const totalTip = roundToTwoDecimals(billAmount * (tipPercent / 100));
  const totalWithTip = roundToTwoDecimals(billAmount + totalTip);
  const perPerson = roundToTwoDecimals(totalWithTip / numPeople);
  const tipPerPerson = roundToTwoDecimals(totalTip / numPeople);

  // Return detailed breakdown (R2)
  return {
    totalBill: billAmount,
    tipPercent,
    totalTip,
    totalWithTip,
    numPeople,
    perPerson,
    tipPerPerson
  };
}

import { expect, it, describe } from 'vitest';
import { splitBill } from './app.js';

describe('splitBill', () => {
  // R1, R2: Standard calculation tests
  it('splits a bill with 20% tip among 4 people', () => {
    const result = splitBill(100, 20, 4);

    expect(result.totalBill).toBe(100);
    expect(result.tipPercent).toBe(20);
    expect(result.totalTip).toBe(20);
    expect(result.totalWithTip).toBe(120);
    expect(result.numPeople).toBe(4);
    expect(result.perPerson).toBe(30);
    expect(result.tipPerPerson).toBe(5);
  });

  it('splits a bill with 15% tip among 2 people', () => {
    const result = splitBill(50, 15, 2);

    expect(result.totalBill).toBe(50);
    expect(result.tipPercent).toBe(15);
    expect(result.totalTip).toBe(7.5);
    expect(result.totalWithTip).toBe(57.5);
    expect(result.numPeople).toBe(2);
    expect(result.perPerson).toBe(28.75);
    expect(result.tipPerPerson).toBe(3.75);
  });

  // Edge cases
  it('handles 0% tip', () => {
    const result = splitBill(100, 0, 2);

    expect(result.totalTip).toBe(0);
    expect(result.totalWithTip).toBe(100);
    expect(result.perPerson).toBe(50);
    expect(result.tipPerPerson).toBe(0);
  });

  it('handles 100% tip', () => {
    const result = splitBill(50, 100, 2);

    expect(result.totalTip).toBe(50);
    expect(result.totalWithTip).toBe(100);
    expect(result.perPerson).toBe(50);
    expect(result.tipPerPerson).toBe(25);
  });

  it('handles 1 person', () => {
    const result = splitBill(100, 20, 1);

    expect(result.perPerson).toBe(120);
    expect(result.tipPerPerson).toBe(20);
  });

  it('handles many people', () => {
    const result = splitBill(100, 20, 10);

    expect(result.perPerson).toBe(12);
    expect(result.tipPerPerson).toBe(2);
  });

  it('handles zero bill amount', () => {
    const result = splitBill(0, 20, 2);

    expect(result.totalBill).toBe(0);
    expect(result.totalTip).toBe(0);
    expect(result.totalWithTip).toBe(0);
    expect(result.perPerson).toBe(0);
  });

  // R4: Rounding tests
  it('rounds tip amount to 2 decimal places', () => {
    const result = splitBill(33.33, 18, 1);

    // 33.33 * 0.18 = 5.9994, should round to 6.00
    expect(result.totalTip).toBe(6);
    expect(result.totalWithTip).toBe(39.33);
  });

  it('rounds per person amount to 2 decimal places', () => {
    const result = splitBill(100, 20, 3);

    // 120 / 3 = 40.00, tip per person = 20 / 3 = 6.666... should round to 6.67
    expect(result.perPerson).toBe(40);
    expect(result.tipPerPerson).toBe(6.67);
  });

  it('rounds fractional cents correctly (rounding down)', () => {
    const result = splitBill(10, 10, 3);

    // 10 * 0.10 = 1.00, total = 11.00
    // 11.00 / 3 = 3.666... should round to 3.67
    // 1.00 / 3 = 0.333... should round to 0.33
    expect(result.perPerson).toBe(3.67);
    expect(result.tipPerPerson).toBe(0.33);
  });

  // R3: Validation tests
  it('throws error for negative bill amount', () => {
    expect(() => splitBill(-10, 20, 2)).toThrow('Bill amount cannot be negative');
  });

  it('throws error for negative tip percentage', () => {
    expect(() => splitBill(100, -5, 2)).toThrow('Tip percentage cannot be negative');
  });

  it('throws error for zero people', () => {
    expect(() => splitBill(100, 20, 0)).toThrow('Number of people must be at least 1');
  });

  it('throws error for negative people count', () => {
    expect(() => splitBill(100, 20, -2)).toThrow('Number of people must be at least 1');
  });

  it('throws error for non-integer people count', () => {
    expect(() => splitBill(100, 20, 2.5)).toThrow('Number of people must be an integer');
  });
});

